def execute_command(image) -> ImagePatch:
    image_patch = ImagePatch(image)
    cats = image_patch.find("cat")
    sofas = image_patch.find("sofa")

    if not cats or not sofas:
        return image_patch

    white_cats = [cat for cat in cats if image_patch.verify_property(cat, "white")]
    if len(white_cats) < 2:
        return image_patch

    sofa_depths = [(sofa, sofa.compute_depth()) for sofa in sofas]
    sofa_depths.sort(key=lambda x: x[1])
    closest_sofa = sofa_depths[0][0]

    behind_cats = [cat for cat in white_cats if cat.overlaps_with(closest_sofa.left, closest_sofa.lower, closest_sofa.right, closest_sofa.upper)]

    if behind_cats:
        return max(behind_cats, key=lambda cat: cat.compute_depth())

    return white_cats[0]

